  "plans.title": "مقایسه طرح‌های StockHaven",
  "plans.intro": "یک حساب، هر طرحی را که انتخاب کنید — Business تا پنج کسب‌وکار را پوشش می‌دهد. قیمت‌ها ماهانه و به دلار آمریکا هستند و مشتریان جدید واجد شرایط وب‌سایت می‌توانند یک دوره آزمایشی هفت‌روزه در مجموع Essentials و Business دریافت کنند. ارتقای اشتراک Essentials موجود به Business دوره آزمایشی را از نو شروع نمی‌کند و دوره آزمایشی رایگان دیگری ایجاد نمی‌کند. قیمت‌های طرح وب‌سایت پیش از مالیات‌های قابل اعمال، در صورت وجود، هستند. مبلغ دقیق شما پیش از اجازه اشتراک نشان داده خواهد شد.",
