  "upgrade.trialHistoryNote": "اگر برای Essentials پرداخت می‌کنید و به Business منتقل می‌شوید، همان حساب مشتری و سابقه دوره آزمایشی را حفظ می‌کنید. Business شامل دوره آزمایشی هفت‌روزه اضافی نیست. اگر در حالی که دوره آزمایشی اصلی شما هنوز در حال اجرا است ارتقا دهید، تاریخ پایان اصلی آن بازنشانی نمی‌شود.",
  "upgrade.providerConfirmNote": "تغییر طرح نیازمند تأیید ارائه‌دهنده صورت‌حساب است. هر تفاوت قیمت، مبلغ تناسبی و تاریخ اجرا باید پیش از تأیید تغییر نشان داده شود. ارتقا نباید اشتراک هم‌زمان دومی ایجاد کند.",
  "upgrade.chargedThroughProviderNote": "تغییر طرح از طریق ارائه‌دهنده صورت‌حساب هزینه می‌شود. می‌توانید اشتراک خود را از این صفحه با دکمه لغو اشتراک زیر طرح فعلی خود، یا از تنظیمات، لغو کنید. لغو تمدیدهای آینده را در پایان دوره پرداخت‌شده شما متوقف می‌کند؛ هرگز دسترسی شما را یکباره پایان نمی‌دهد. فضای‌های کاری رایگان موجود با مشاهده این گزینه‌ها هزینه نمی‌شوند.",
