  "import.excelNote": "کتاب‌های کار Excel (.xlsx) مستقیماً خوانده می‌شوند — برگه را انتخاب کنید و ستون‌ها برای شما تطبیق داده می‌شوند. کدها کامل می‌مانند: UPC ذخیره‌شده به‌عنوان متن ارقام و صفرهای ابتدایی خود را حفظ می‌کند. ردیف‌هایی که نمی‌توان وارد کرد با دلیل فهرست می‌شوند",
