  "print.supplierBlockedDesc": "اسناد تأمین‌کننده با طرح Business همراه هستند — تأمین‌کنندگان، خرید و سفارش‌های خرید. همه‌چیز که اکنون دارید به کار خود ادامه می‌دهد.",
  "print.seeBusiness": "مشاهده آنچه Business شامل می‌شود",
  "print.nothingToPrint": "هنوز چیزی برای چاپ نیست",
  "print.pickOrderHint": "سفارش خریدی از فهرست انتخاب کنید تا سند را پیش‌نمایش کنید.",
  "print.pickCustomerOrderHint": "سفارش مشتری از فهرست انتخاب کنید تا سند را پیش‌نمایش کنید.",
  "print.pickReturnHint": "بازگشت ثبت‌شده‌ای از فهرست انتخاب کنید تا سند را پیش‌نمایش کنید.",
  "print.chooseStyleHint": "سبکی انتخاب کنید، سپس محصولات را از فهرست انتخاب کنید. پیش‌نمایش دقیقاً آنچه را از چاپگر بیرون می‌آید نشان می‌دهد.",
  "print.howToReach": "چگونه به چاپگر خود برسید",
  "print.howIntro": "این برنامه به چاپگرهایی که از قبل دارید متصل می‌شود — خودش چاپگر نیست. چهار راه برای رسیدن به یکی وجود دارد و برچسب‌ها روی هر دو طرح از طریق هر یک از آن‌ها چاپ می‌شوند. برگه‌های بسته‌بندی، سفارش‌های خرید، اسناد تأمین‌کننده و گزارش‌ها فقط Business هستند، هر اتصالی که باشد.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "از این صفحه، در Chrome یا Edge دسکتاپ و در Chrome اندروید: چاپگر برچسب خود را انتخاب کنید و برچسب‌ها مستقیماً به آن می‌روند. در Safari آیفون کار نمی‌کند — در آیفون، چاپ Bluetooth همراه با برنامه موبایل می‌آید. چاپگری که فقط به زبان ZPL زیبرا یا زبان خود Brother صحبت می‌کند برچسب‌هایی را که این صفحه ارسال می‌کند درک نخواهد کرد؛ این در برابر چاپگرهای واقعی بررسی می‌شود پیش از اینکه کارکردن نامیده شود.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "چاپگر را روی Wi-Fi فروشگاه خود نصب کنید، سپس از دکمه چاپ استفاده کنید — از طریق چاپگر نصب‌شده روی این رایانه، از طریق شبکه فروشگاه چاپ می‌کند. در آیفون، AirPrint داخلی است: چاپگر AirPrint روی همان Wi-Fi فقط در برگه چاپ ظاهر می‌شود، بدون سیم و بدون نیاز به برنامه، و برنامه به کد خاص AirPrint نیاز ندارد. چاپگر باید از AirPrint پشتیبانی کند (بیشتر چاپگرهای جدید این کار را می‌کنند) و تلفن و چاپگر باید روی همان Wi-Fi باشند.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "چاپگر را با سیم Ethernet به شبکه فروشگاه خود وصل کنید، آن را روی رایانه نصب کنید و از طریق دکمه چاپ چاپ کنید. Ethernet مسیر دسکتاپ و رایانه است — آیفون‌ها از سیم Ethernet استفاده نمی‌کنند.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "چاپگر را با سیم آن به رایانه وصل کنید و از دکمه چاپ استفاده کنید — از طریق چاپگر نصب‌شده در آنجا چاپ می‌کند. در تلفن اندروید با کابل USB OTG، دکمه USB بالا مستقیماً با چاپگر صحبت می‌کند. آیفون‌ها نمی‌توانند مستقیماً از طریق USB چاپ کنند — WebUSB در آنجا نیست — بنابراین از Wi-Fi / AirPrint استفاده کنید، یا از Bluetooth در برنامه موبایل.",
  "print.howCordsLead": "سیم‌ها هنوز به آیفون‌ها خدمت می‌کنند، یک قدم دورتر.",
  "print.howCordsBody": "چاپگر USB وصل‌شده به رایانه فروشگاه، یا چاپگر Ethernet سیم‌کشی‌شده به شبکه، روی آیفون شما از طریق Wi-Fi فروشگاه ظاهر می‌شود (AirPrint / چاپگر اشتراکی) — سیم‌ها چاپگر را محکم روی شبکه قرار می‌دهند و تلفن به‌صورت بی‌سیم به آن می‌رسد.",
  "print.howOfflineLead": "اگر اینترنت قطع شود،",
  "print.howOfflineBody": "برچسب‌ها و اسنادی که از قبل روی این صفحه هستند هنوز چاپ می‌شوند — دکمه چاپ، PDF برچسب‌ها، Bluetooth و USB به اتصال نیاز ندارند. آنچه به اینترنت نیاز دارد بارگذاری صفحه و محصولات آن در وهله اول است. حالت آفلاین کامل (کار در برنامه بدون هیچ اتصالی) ساختی جداگانه و بزرگ‌تر است و در اینجا ادعا نمی‌شود.",
