  "settings.title": "تنظیمات",
  "settings.trial.cancelKeeps": "لغو در طول دوره آزمایشی، 7 روز کامل شما را حفظ می‌کند — دسترسی در {date} پایان می‌یابد و از شما مبلغی کسر نخواهد شد.",
  "staff.access.noSeatBody": "حساب شما برای این کسب‌وکار جای کارکنان ندارد، بنابراین موجودی آن بسته می‌ماند. از مالک بخواهید شما را در کارکنان و نقش‌ها اضافه کند.",
  "staff.access.noSeatTitle": "این کسب‌وکار برای ورود شما باز نیست",
  "staff.access.pendingBody": "این کسب‌وکار دعوتی برای ایمیل شما دارد که فعال نشده است. از مالک بخواهید وضعیت کارکنان شما را فعال کند. تا آن زمان هیچ‌چیز در اینجا قابل مشاهده نیست.",
  "staff.access.pendingTitle": "دعوت شما هنوز فعال نیست",
  "staff.access.signOut": "خروج",
  "staff.access.suspendedBody": "مدیر این حساب کارکنان را برای کسب‌وکار فعال تعلیق کرده است. از آن‌ها بخواهید شما را به فعال برگردانند، سپس دوباره وارد شوید.",
  "staff.access.suspendedTitle": "دسترسی شما متوقف شده است",
  "staff.addFirst": "اضافه کردن اولین کارمند",
  "staff.addMember": "اضافه کردن کارمند",
  "staff.emptyBody": "شخصی را اضافه کنید، به او نقشی و مجوزهای همراه آن بدهید و او با ایمیل دعوت می‌شود تا وارد این کسب‌وکار شود.",
  "staff.emptyTitle": "هنوز کارمندی نیست",
  "staff.eyebrow": "تیم",
  "staff.how.p1": "هر عضو نقشی و فهرست مجوز خودش را دارد، بنابراین می‌توانید از نقشی شروع کنید و یک چیز را بدون ساخت نقش جدید تغییر دهید. ویرایش نقش اعضایی را که از قبل روی آن هستند بازنویسی نمی‌کند — عضوی را باز کنید تا پیش‌فرض‌های نقش او دوباره اعمال شود.",
  "staff.how.p2": "نقش‌های سفارشی یک ویژگی Business هستند: Essentials از پنج نقش داخلی استفاده می‌کند (مالک، مدیر، کارمند انبار، کارمند فروش، بیننده).",
  "staff.how.p3": "دعوت‌ها با ایمیل ارسال می‌شوند. عضو فقط زمانی می‌تواند وارد شود که بپذیرد و حذف کسی از این فهرست حساب برنامه او را حذف نمی‌کند.",
  "staff.how.p4": "فروشگاه مکانی است که شخص به آن اختصاص داده شده است. روی کارت او ثبت می‌شود؛ آنچه می‌تواند باز کند هنوز توسط نقش و مجوزهای او تعیین می‌شود.",
  "staff.how.p5": "مجوزها تعیین می‌کنند هر شخص چه چیزی را می‌تواند باز کند: موارد منو خارج از نقش آن‌ها پنهان هستند و نشانی مسدودشده به جای صفحه، اخطار «روی نقش شما نیست» نشان می‌دهد. تغییر دفعه بعد که آن شخص برنامه را بارگذاری کند اعمال می‌شود؛ تعلیق عضو او را به‌طور کامل قفل می‌کند.",
  "staff.how.p6": "مدیران می‌توانند همه داده‌ها را ببینند و تغییر دهند، کاربران و نقش‌های برنامه را مدیریت کنند و هرگز توسط نقش کارکنان محدود نمی‌شوند. کسی بدون سابقه کارکنان — مالک کسب‌وکار جدید — دسترسی کامل را حفظ می‌کند.",
  "staff.howTitle": "کارکنان و نقش‌ها چگونه کار می‌کنند",
