  "workforce.tab.rewards": "پاداش‌ها",
  "training.lessons.mgr-give-rewards.step1": "نیروی کار را باز کنید و روی پاداش‌ها بزنید. عضو تیم را انتخاب کنید، سپس نوع را: یک درصد تخفیف در فروشگاه، یک کارت هدیه، یا چیز دیگری که با کلمات خودتان توصیف می‌کنید.",
  "training.lessons.mgr-give-rewards.step2": "به پاداش یک نام کوتاه و یک یادداشت اگر دوست دارید بدهید. شخص بلافاصله یک زنگ دریافت می‌کند، و پاداش در پاداش‌های من او با کد خودش منتظر می‌ماند.",
  "training.lessons.mgr-give-rewards.step3": "مرز، بر اساس طراحی: شما فقط به کارکنان پاداش می‌دهید. نمی‌توانید به خودتان یا یک مدیر دیگر پاداش دهید — پاداش دادن به یک مدیر تصمیم مالک است، و برنامه آن را صریح رد می‌کند.",
  "training.lessons.mgr-give-rewards.step4": "در صندوق، کدی را که عضو تیم به شما نشان می‌دهد تایپ کنید و آن را به عنوان استفاده‌شده علامت‌گذاری کنید — هر کد یک بار کار می‌کند. می‌توانید پاداشی را که دادید اگر برنامه‌ها تغییر کردند باطل کنید؛ هدایای مالک مال مالک هستند که باطل کند.",
  "training.lessons.mgr-give-rewards.title": "دادن پاداش به کارکنان شما",
  "training.lessons.owner-give-rewards.step1": "پاداش‌ها در نیروی کار، در زبانه پاداش‌ها زندگی می‌کنند، و فقط برای طرح Business هستند — در Essentials زبانه یک در قفل‌شده نشان می‌دهد، تا تیم شما بتواند ببیند طرح بزرگ‌تر چه چیزی دارد.",
  "training.lessons.owner-give-rewards.step2": "می‌توانید به هر کسی در تیم پاداش دهید — کارکنان و مدیران به یک اندازه. شخص را انتخاب کنید، سپس نوع را: یک درصد تخفیف در فروشگاه (هر درصدی که انتخاب می‌کنید)، یک کارت هدیه به هر جا، یا هر مشوقی که با کلمات خودتان توصیف می‌کنید.",
  "training.lessons.owner-give-rewards.step3": "پاداش با کد یک‌بارمصرف خودش فرود می‌آید و زنگ شخص را به صدا درمی‌آورد. آن‌ها کد را در صندوق نشان می‌دهند؛ یک مالک یا مدیر آن را تایپ می‌کند تا به عنوان استفاده‌شده علامت‌گذاری شود.",
  "training.lessons.owner-give-rewards.step4": "یک رسید پاداش چاپ‌شده یا به‌اشتراک‌گذاشته‌شده فقط نام کسب‌وکار شما را دارد — هرگز نام برنامه را نه. این تشکر فروشگاه شماست، نه یک تبلیغ.",
  "training.lessons.owner-give-rewards.title": "دادن پاداش‌ها (طرح Business)",
  "training.lessons.owner-rewards-oversight.step1": "مدیر شما هم می‌تواند پاداش دهد — فقط به کارکنان. برنامه مدیری را که به خودش یا یک مدیر دیگر پاداش دهد رد می‌کند؛ پاداش دادن به یک مدیر همیشه تصمیم شماست.",
  "training.lessons.owner-rewards-oversight.step2": "شما هر پاداش در کسب‌وکار را در تاریخچه پاداش می‌بینید: چه کسی آن را داد، چه کسی آن را گرفت، و آیا آماده، استفاده‌شده یا باطل است. یک مدیر فقط پاداش‌هایی را می‌بیند که داد و آن‌هایی را که دریافت کرد.",
  "training.lessons.owner-rewards-oversight.step3": "می‌توانید هر پاداشی را باطل کنید، از جمله یکی که مدیر شما داد. یک مدیر می‌تواند هدایای خودش را باطل کند، اما هرگز مال شما را نه.",
  "training.lessons.owner-rewards-oversight.step4": "هر کد دقیقاً یک بار کار می‌کند، و یک پاداش باطل‌شده هرگز نمی‌تواند استفاده شود — تاریخچه همیشه نشان می‌دهد یک پاداش چگونه تمام شد.",
  "training.lessons.owner-rewards-oversight.title": "نظارت بر پاداش‌ها: دادن مدیر شما",
  "training.lessons.staff-your-rewards.step1": "وقتی مدیر یا مالک شما به شما پاداشی می‌دهد، زنگ شما به صدا درمی‌آید. نیروی کار را باز کنید و روی پاداش‌ها بزنید تا آن را زیر پاداش‌های من ببینید.",
  "training.lessons.staff-your-rewards.step2": "هر پاداش کد خودش را دارد. آن را نزد خودتان نگه دارید — هر کسی که کد را در صندوق نشان دهد همان کسی است که از پاداش استفاده می‌کند.",
  "training.lessons.staff-your-rewards.step3": "برای استفاده از آن، وقتی می‌خرید کد را نشان دهید. شخص در صندوق آن را تایپ می‌کند و به عنوان استفاده‌شده علامت‌گذاری می‌کند — هر کد دقیقاً یک بار کار می‌کند.",
  "training.lessons.staff-your-rewards.step4": "پاداش‌ها یک لذت طرح Business هستند. اگر فروشگاه شما در Business نیست، زبانه پاداش‌ها به جای آن یک در قفل‌شده نشان می‌دهد — این طرح است، نه یک اشتباه.",
  "training.lessons.staff-your-rewards.title": "پاداش‌های شما: پیدا کردن کد شما و استفاده از آن",
  "training.module.rewards": "پاداش‌ها و مشوق‌ها",
