  "pricing.clearanceBadge": "تصفیه",
  "pricing.clearanceHint": "یک کاهش دائمی. تا زمانی که آن را به قیمت معمول برگردانید، می‌ماند.",
  "pricing.clearancePriceLabel": "قیمت تصفیه",
  "pricing.endLabel": "پایان",
  "pricing.modeClearance": "تصفیه",
  "pricing.modeLabel": "قیمت‌ها",
  "pricing.modeRegular": "قیمت معمول",
  "pricing.modeRollback": "تخفیف موقت (فروش موقت)",
  "pricing.rollbackBadge": "تخفیف",
  "pricing.rollbackHint": "قیمت معمول نگه داشته می‌شود و در طول فروش، کنار قیمت تخفیف موقت نشان داده می‌شود. وقتی تاریخ پایان بگذرد، قیمت خودش به قیمت معمول برمی‌گردد.",
  "pricing.rollbackStarts": "تخفیف موقت از {date} شروع می‌شود",
  "pricing.salePriceLabel": "قیمت تخفیف موقت",
  "pricing.sectionTitle": "قیمت‌های فروش",
  "pricing.startLabel": "شروع",
  "training.lessons.mgr-pricing.step1": "در Business، فرم محصول بخشی برای قیمت‌های فروش دارد. تصفیه یک کاهش دائمی است — تعیینش کنید و می‌ماند. تخفیف موقت فروشی با تاریخ است: قیمت تخفیف، روز شروع و روز پایان را تعیین کنید.",
  "training.lessons.mgr-pricing.step2": "هرگز لازم نیست قیمت معمول را دوباره بنویسید: روی محصول می‌ماند و در فهرست محصولات و اسکنر کنار قیمت فروش نشان داده می‌شود، تا هر کسی ببیند کالا معمولاً چقدر قیمت دارد.",
  "training.lessons.mgr-pricing.step3": "وقتی تخفیف موقت شروع می‌شود برچسب‌های قیمت تازه چاپ کنید — برچسب‌ها قیمتی را چاپ می‌کنند که مشتری آن روز می‌پردازد. وقتی تاریخ پایان بگذرد، قیمت خودش به قیمت معمول برمی‌گردد؛ وقتی قفسه را تازه می‌کنید برچسب‌های معمول را دوباره چاپ کنید.",
  "training.lessons.mgr-pricing.step4": "اگر بخش قیمت‌های فروش قفل نشان داده می‌شود، کسب‌وکار روی طرح Business نیست — قیمت‌های فروش به آن طرح تعلق دارند، و صاحب‌کسب‌وکار است که طرح‌ها را تغییر می‌دهد.",
  "training.lessons.mgr-pricing.title": "برگزاری فروش: تصفیه‌ها و تخفیف‌های موقت",
  "training.lessons.owner-pricing.step1": "دو نوع کاهش در فرم محصول، زیر قیمت‌های فروش، زندگی می‌کنند. تصفیه دائمی است: قیمت تصفیه را تعیین کنید و تا زمانی که آن را برگردانید پایین می‌ماند. تخفیف موقت یک فروش موقت است — قیمتی پایین‌تر با تاریخ شروع و تاریخ پایان، مانند فروش‌هایی که از فروشگاه‌های بزرگ می‌شناسید.",
  "training.lessons.owner-pricing.step2": "قیمت معمول هرگز پاک نمی‌شود. در طول تخفیف موقت، برنامه قیمت فروش را با قیمت معمول در کنارش نشان می‌دهد، و برچسب‌های چاپی قیمت فروش را دارند، تا قفسه با صندوق هماهنگ باشد.",
  "training.lessons.owner-pricing.step3": "وقتی تاریخ پایان بگذرد، قیمت خودش به قیمت معمول برمی‌گردد — چیزی برای به خاطر سپردن نیست، چیزی برای برگرداندن نیست. تخفیف موقتی که هنوز شروع نشده، تاریخ شروعش را درست در فهرست محصولات می‌گوید.",
  "training.lessons.owner-pricing.step4": "قیمت‌های فروش ویژگی طرح Business هستند. در Essentials فیلدها قفل می‌مانند، و اگر کسب‌وکاری به Essentials برود و برگردد، تنظیمات تصفیه و تخفیف موقتش هنوز آنجاست، دقیقاً همان‌طور که گذاشته شده بود.",
  "training.lessons.owner-pricing.title": "قیمت‌های تصفیه و تخفیف موقت (طرح Business)",
  "plansLib.includes.shippingLabels": "برچسب‌های ارسال 4×6 برای سفارش‌های مشتری",
  "print.templateShipping": "برچسب ارسال",
  "print.templateShippingHint": "برچسب 4×6 با نام و نشانی خریدار",
  "print.shipFrom": "از",
  "print.recipientNameLabel": "نام گیرنده",
  "print.recipientAddressLabel": "نشانی گیرنده",
  "print.senderAddressLabel": "نشانی شما (فرستنده)",
  "print.shippingNote": "نشانی‌ها هنگام چاپ نوشته می‌شوند و ذخیره نمی‌شوند. نام گیرنده از سفارش پر می‌شود.",
  "training.lessons.owner-shipping-labels.step1": "مرکز چاپ در هر دو طرح سبک برچسب ارسال دارد: سفارش مشتری را انتخاب کنید و برچسب 4×6 با نام و نشانی خریدار و کسب‌وکار شما به‌عنوان فرستنده چاپ کنید.",
  "training.lessons.owner-shipping-labels.step2": "برچسب سفیدبرچسب است، مانند هر سند مشتری: فقط نام کسب‌وکار شما را دارد — هرگز نام این برنامه را نه — تا بسته‌ای از فروشگاه شما چنان به نظر برسد که از فروشگاه شما آمده است.",
